/*  viora.js  -  Viora, the talking rehab buddy (3D mascot widget)
 *
 *  Plain HTML site:  see example.html (2 small blocks + this file + doctor_3d.fbx)
 *  React / Vite / npm: npm install three, then
 *        import { initViora } from './viora.js';   initViora({ model: '/doctor_3d.fbx' });
 *
 *  Options (all optional):
 *    model            URL of the FBX file (default: doctor_3d.fbx next to this file)
 *    lines            array of sentences Viora says when clicked
 *    tag              text on the name tag, e.g. 'Viora · Game Guide'
 *    side             'right' (default) or 'left'
 *    greetOnFirstClick  false to turn off the greeting on the first click
 *
 *  With the plain <script> tag, set options BEFORE it:
 *        <script>window.VIORA_OPTIONS = { tag: 'Viora · Game Guide', side: 'left' };</script>
 *
 *  From your game code:   Viora.say('Level complete! Great job!');
 */
import * as THREE from 'three';
import { FBXLoader } from 'three/addons/loaders/FBXLoader.js';

const DEFAULT_MODEL = new URL('doctor_3d.fbx', import.meta.url).href;

const CSS = `  #viora-widget {
    position: fixed; right: 20px; bottom: 20px; width: 230px;
    z-index: 9999; font-family: 'Segoe UI', Arial, sans-serif;
  }
  #viora-stage { width: 230px; height: 320px; cursor: pointer; position: relative; }
  #viora-status {
    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
    text-align: center; font-size: .8rem; color: #0f766e; padding: 8px; pointer-events: none;
  }
  #viora-bubble {
    display: none; position: absolute; bottom: 100%; right: 0;
    width: 250px; margin-bottom: 6px; padding: 10px 14px;
    background: #fff; border-radius: 14px; font-size: .9rem; color: #1d3b3a;
    box-shadow: 0 4px 14px rgba(0,0,0,.15);
  }
  #viora-bubble.show { display: block; }
  #viora-tag {
    display: block; margin: 0 auto; width: fit-content;
    background: #0f766e; color: #fff; padding: 4px 16px;
    border-radius: 999px; font-size: .8rem; font-weight: 600;
  }
`;

export function initViora(opts = {}) {
  if (document.getElementById('viora-widget')) return;   // never create him twice
  const MODEL_URL = opts.model || DEFAULT_MODEL;

  const style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  const widget = document.createElement('div');
  widget.id = 'viora-widget';
  widget.innerHTML = `
    <div id="viora-bubble" class="show">Hi! Click me 👋</div>
    <div id="viora-stage" title="Click to talk to Viora">
      <div id="viora-status">Loading Viora…</div>
    </div>
    <span id="viora-tag"></span>`;
  widget.querySelector('#viora-tag').textContent = opts.tag || 'Viora · Rehab Buddy';
  document.body.appendChild(widget);
  if (opts.side === 'left') { widget.style.right = 'auto'; widget.style.left = '20px'; }

  const stage  = document.getElementById('viora-stage');
  const bubble = document.getElementById('viora-bubble');
  const status = document.getElementById('viora-status');
  const W = stage.clientWidth, H = stage.clientHeight;

  if (location.protocol === 'file:') {
    status.textContent = 'Open this page with Live Server (not by double-clicking).';
  }

  /* ---------------- 3D SCENE ---------------- */
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(window.devicePixelRatio);
  renderer.setSize(W, H);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  stage.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(35, W / H, 0.01, 1000);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x888888, 2.2));
  const sun = new THREE.DirectionalLight(0xffffff, 1.5);
  sun.position.set(1, 2, 3);
  scene.add(sun);

  const pivot = new THREE.Group();
  scene.add(pivot);
  let height = 1, talking = false, pulse = 0;

  /* Texture is embedded in this file, so no separate image is needed.
     Its UV coordinates are negative, so it must use RepeatWrapping. */
  const TEXTURE_DATA = 'data:image/jpeg;base64,';
  const texture = new THREE.TextureLoader().load(TEXTURE_DATA);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;

  /* Mouth that opens and closes while Viora speaks */
  const mouth = new THREE.Mesh(
    new THREE.SphereGeometry(1, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0x4a0d14, roughness: 0.6 })
  );
  const MOUTH_X = 0.007, MOUTH_Y = 0.106, MOUTH_Z = 0.131;   // nudge these if the mouth looks misplaced
  mouth.position.set(MOUTH_X, MOUTH_Y, MOUTH_Z);
  mouth.visible = false;
  let mouthOpen = 0;

  new FBXLoader().load(
    MODEL_URL,
    (obj) => {
      obj.traverse((child) => {
        if (child.isMesh) {
          child.material = new THREE.MeshStandardMaterial({
            map: texture, roughness: 0.85, metalness: 0, side: THREE.DoubleSide
          });
          if (!mouth.parent) child.add(mouth);
        }
      });

      const box = new THREE.Box3().setFromObject(obj);
      const center = box.getCenter(new THREE.Vector3());
      height = box.max.y - box.min.y;
      obj.position.sub(center);
      pivot.add(obj);

      const fov = THREE.MathUtils.degToRad(camera.fov);
      const dist = (height / 2) / Math.tan(fov / 2) * 1.5;   // extra room so the head is never cut off
      camera.position.set(0, 0, dist);
      camera.lookAt(0, 0, 0);

      status.remove();
    },
    undefined,
    (err) => {
      console.error('Viora load error:', err);
      status.textContent = 'Could not load doctor_3d.fbx. Check the file name and folder.';
    }
  );

  /* ---------------- ANIMATION ---------------- */
  const clock = new THREE.Clock();
  let t = 0;
  renderer.setAnimationLoop(() => {
    const dt = clock.getDelta();
    t += dt;
    pulse = Math.max(0, pulse - dt * 4);          // decays after each spoken word

    if (talking) {
      pivot.position.y = (Math.abs(Math.sin(t * 8)) * 0.008 + pulse * 0.014) * height;
      pivot.rotation.y = Math.sin(t * 1.6) * 0.2;
      pivot.rotation.z = Math.sin(t * 3) * 0.04;
      pivot.rotation.x = -0.05 * pulse;
    } else {
      pivot.position.y = Math.sin(t * 1.5) * 0.004 * height;
      pivot.rotation.y = Math.sin(t * 0.6) * 0.15;
      pivot.rotation.z *= 0.9;
      pivot.rotation.x *= 0.9;
    }

    // mouth: opens and closes with the speech
    const target = talking ? Math.min(1, 0.25 + 0.55 * Math.abs(Math.sin(t * 11)) + 0.3 * pulse) : 0;
    mouthOpen += (target - mouthOpen) * Math.min(1, dt * 18);
    mouth.visible = mouthOpen > 0.06;
    mouth.scale.set(0.026, 0.003 + mouthOpen * 0.018, 0.008);

    renderer.render(scene, camera);
  });

  /* ---------------- VOICE ---------------- */
  let voices = [];
  function loadVoices() {
    voices = speechSynthesis.getVoices();
    if (voices.length) {
      console.log('Viora voices:', voices.map(v => v.name + ' (' + v.lang + ', ' + (v.localService ? 'local' : 'online') + ')'));
    }
  }
  loadVoices();
  speechSynthesis.onvoiceschanged = loadVoices;

  // Boy/male English voices first. Voices stored on this computer come before online ones,
  // because online voices often stay silent when the connection is blocked.
  const MALE   = /\bMale\b|David|Mark|James|Guy|Ryan|Christopher|Eric|Roger|Steffan|Prabhat|Ravi|Rishi|Daniel|Alex|Fred|Aaron|Arthur|Oliver|Thomas|Brian|George|Liam/i;
  const FEMALE = /Female|Zira|Heera|Neerja|Aria|Jenny|Sonia|Samantha|Susan|Hazel|Linda|Karen|Moira|Tessa|Veena|Libby|Natasha|Clara|Emma|Ava/i;
  const isMale = (v) => !!v && MALE.test(v.name) && !FEMALE.test(v.name);

  function rankedVoices() {
    const en = voices.filter((v) => /^en/i.test(v.lang));
    const pool = en.length ? en : voices;
    const score = (v) => {
      let sc = 0;
      if (isMale(v)) sc += 20;
      if (FEMALE.test(v.name)) sc -= 20;
      if (v.localService) sc += 10;
      if (/en-IN/i.test(v.lang)) sc += 2;
      if (/natural/i.test(v.name)) sc += 1;
      return sc;
    };
    return [...pool].sort((x, y) => score(y) - score(x));
  }

  let audioCtx;
  function chime() {
    try {
      audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();
      const now = audioCtx.currentTime;
      [660, 880].forEach((freq, i) => {
        const o = audioCtx.createOscillator();
        const g = audioCtx.createGain();
        o.type = 'sine';
        o.frequency.value = freq;
        g.gain.setValueAtTime(0, now + i * 0.13);
        g.gain.linearRampToValueAtTime(0.12, now + i * 0.13 + 0.03);
        g.gain.exponentialRampToValueAtTime(0.001, now + i * 0.13 + 0.35);
        o.connect(g).connect(audioCtx.destination);
        o.start(now + i * 0.13);
        o.stop(now + i * 0.13 + 0.4);
      });
    } catch (e) { /* sound is optional */ }
  }

  const lines = opts.lines || [
    "Hello! I am Viora, your rehabilitation buddy. I am so happy to see you today!",
    "Great job showing up today! Every small step counts, and I am proud of you.",
    "Take a deep breath. Move slowly, stay relaxed, and never push through sharp pain. Follow your therapist's guidance.",
    "You are stronger than you think. Let's keep going, one step at a time!"
  ];
  let next = 0, greeted = false, hideTimer, token = 0, goodVoice = null;

  function speak(text) {
    greeted = true;
    clearTimeout(hideTimer);
    const id = ++token;                 // newest line wins; older attempts are ignored
    speechSynthesis.cancel();
    speechSynthesis.resume();
    bubble.textContent = text;
    bubble.classList.add('show');
    chime();
    setTimeout(() => attempt(text, 0, id), 350);
  }

  // Tries voices one by one until one really starts talking.
  function attempt(text, n, id) {
    if (id !== token) return;
    const candidates = [...new Set([goodVoice, ...rankedVoices()].filter(Boolean)), null];
    if (n >= Math.min(candidates.length, 6)) {
      talking = false;
      bubble.textContent = text + '  (No voice could play. Try Microsoft Edge or Chrome, and check your sound and installed voices.)';
      hideTimer = setTimeout(() => bubble.classList.remove('show'), 7000);
      return;
    }
    const v = candidates[n];
    const u = new SpeechSynthesisUtterance(text);
    if (v) { u.voice = v; u.lang = v.lang; } else { u.lang = 'en-US'; }
    u.rate = 1;
    u.pitch = isMale(v) ? 1.2 : 0.75;   // slightly higher = youthful boy voice
    u.volume = 1;

    let started = false;
    const retry = () => {
      if (id !== token) return;
      speechSynthesis.cancel();
      const nid = ++token;
      setTimeout(() => attempt(text, n + 1, nid), 250);
    };

    u.onstart = () => { if (id !== token) return; started = true; goodVoice = v; talking = true; console.log('Viora is speaking with:', v ? v.name : 'default voice'); };
    u.onboundary = (e) => { if (id === token && e.name === 'word') pulse = 1; };
    u.onend = () => {
      if (id !== token) return;
      talking = false;
      hideTimer = setTimeout(() => bubble.classList.remove('show'), 3500);
    };
    u.onerror = (e) => {
      if (id !== token) return;
      if (e.error === 'interrupted' || e.error === 'canceled') return;
      if (!started) retry();
      else { talking = false; hideTimer = setTimeout(() => bubble.classList.remove('show'), 3500); }
    };

    speechSynthesis.speak(u);
    setTimeout(() => { if (id === token && !started) retry(); }, 2000);   // silent? try the next voice
  }

  stage.onclick = () => { speak(lines[next]); next = (next + 1) % lines.length; };

  // Browsers only allow sound after a click, so the first click anywhere makes Viora greet.
  if (opts.greetOnFirstClick !== false) document.addEventListener('pointerdown', (e) => {
    if (!greeted && !stage.contains(e.target)) {
      speak(lines[0]);
      next = 1;
    }
  });

  window.Viora = { say: (text) => speak(text) };
}

// Loaded with <script type="module" src="viora.js">  ->  start automatically.
// Loaded through a bundler (React/Vite)               ->  call initViora() yourself.
if (document.querySelector('script[src*="viora.js"]')) {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => initViora(window.VIORA_OPTIONS || {}));
  } else {
    initViora(window.VIORA_OPTIONS || {});
  }
}
